'use strict';
// Users, roles and permissions. The acting user comes from a signed sign-in token (server/auth.js), or from the
// X-GT-User header when GT_AUTH=demo; the user's roles decide what the API allows (and what the UI shows).

/**
 * Modules generated by UI Forge live in server/generated (index.js is rewritten by the generator). Their
 * permissions join the catalogue below, so roles, the API and the display registry all know them.
 * Without that folder nothing changes.
 */
const generated = (() => {
  try {
    return require('./generated');
  } catch (e) {
    if (e.code === 'MODULE_NOT_FOUND' && String(e.message).includes(`'./generated'`)) return null;
    throw e;
  }
})();

/** Every permission, grouped by module. The UI's role editor renders this as a matrix. */
const BASE_MODULES = [
  { module: 'dashboard', label: 'Dashboard', actions: ['view'] },
  { module: 'contracts', label: 'Contracts', actions: ['view', 'edit', 'delete', 'approve'] },
  { module: 'trades', label: 'Trading', actions: ['view', 'edit', 'delete', 'approve'] },
  { module: 'data', label: 'Time Series & Data Ingestion', actions: ['view', 'edit'] },
  { module: 'reference', label: 'Reference Data', actions: ['view', 'edit', 'delete'] },
  { module: 'audit', label: 'Audit Trail', actions: ['view'] },
  { module: 'users', label: 'User Management', actions: ['view', 'manage'] },
  { module: 'displays', label: 'Menus & Displays', actions: ['register'] }
];
const MODULES = BASE_MODULES.map(m => Object.assign({}, m, { actions: m.actions.slice() }));
for (const g of (generated && generated.permissionModules) || []) {
  const m = MODULES.find(x => x.module === g.module);
  if (m) g.actions.forEach(a => { if (!m.actions.includes(a)) m.actions.push(a); });
  else MODULES.push({ module: g.module, label: g.label, actions: g.actions.slice() });
}
const ACTION_LABELS = Object.assign({ view: 'View', edit: 'Create & edit', delete: 'Delete', approve: 'Approve / confirm', manage: 'Manage users & roles', register: 'Register menus & displays' },
  (generated && generated.actionLabels) || {});
const ALL = [].concat(...MODULES.map(m => m.actions.map(a => `${m.module}.${a}`)));
const VIEW_ALL = MODULES.filter(m => m.module !== 'users' && m.module !== 'displays').map(m => `${m.module}.view`);

function seedRoles() {
  return [
    { id: 1, name: 'Administrator', description: 'Full access, including users and roles', isSystem: true, permissions: ALL.slice() },
    { id: 2, name: 'Trader', description: 'Captures contracts and trades', isSystem: false,
      permissions: VIEW_ALL.concat(['contracts.edit', 'trades.edit', 'trades.delete']) },
    { id: 3, name: 'Operations', description: 'Confirms trades, loads data, maintains reference data', isSystem: false,
      permissions: VIEW_ALL.concat(['trades.approve', 'data.edit', 'reference.edit', 'reference.delete']) },
    { id: 4, name: 'Risk Manager', description: 'Approves contracts and confirms trades', isSystem: false,
      permissions: VIEW_ALL.concat(['contracts.approve', 'trades.approve']) },
    { id: 5, name: 'Read Only', description: 'Can see everything except user management, changes nothing', isSystem: false,
      permissions: VIEW_ALL.slice() }
  ];
}

function seedUsers(now) {
  const at = days => new Date(now.getTime() - days * 86400000).toISOString();
  return [
    { id: 1, username: 'demo.trader', fullName: 'Demo Trader', email: 'demo.trader@gridtrade.example', department: 'Front Office', roleIds: [2], enabled: true, createdAt: at(400) },
    { id: 2, username: 'ops.analyst', fullName: 'Ops Analyst', email: 'ops.analyst@gridtrade.example', department: 'Operations', roleIds: [3], enabled: true, createdAt: at(400) },
    { id: 3, username: 'risk.manager', fullName: 'Risk Manager', email: 'risk.manager@gridtrade.example', department: 'Risk', roleIds: [4], enabled: true, createdAt: at(400) },
    { id: 4, username: 'admin', fullName: 'System Administrator', email: 'admin@gridtrade.example', department: 'IT', roleIds: [1], enabled: true, createdAt: at(420) },
    { id: 5, username: 'auditor', fullName: 'Internal Auditor', email: 'auditor@gridtrade.example', department: 'Compliance', roleIds: [5], enabled: true, createdAt: at(200) },
    { id: 6, username: 'former.trader', fullName: 'Former Trader', email: 'former.trader@gridtrade.example', department: 'Front Office', roleIds: [2], enabled: false, createdAt: at(380) }
  ];
}

/** Adds users/roles to databases created before user management existed. */
function ensure(db) {
  let changed = false;
  if (!Array.isArray(db.roles)) { db.roles = seedRoles(); db.seq.roles = db.roles.length; changed = true; }
  if (!Array.isArray(db.users)) { db.users = seedUsers(new Date()); db.seq.users = db.users.length; changed = true; }
  // Permissions added in later versions go to the Administrator (system) role, which always holds them all.
  db.roles.filter(r => r.isSystem).forEach(r => {
    ALL.forEach(p => { if (!r.permissions.includes(p)) { r.permissions.push(p); changed = true; } });
  });
  // A generated module may grant its permissions to existing roles. Each grant is applied once, so an
  // administrator who later removes the permission from the role keeps that decision.
  for (const g of (generated && generated.permissionModules) || []) {
    for (const [roleName, actions] of Object.entries(g.grants || {})) {
      const key = `${g.module}:${roleName}`;
      db.appliedGrants = db.appliedGrants || [];
      if (db.appliedGrants.includes(key)) continue;
      const role = db.roles.find(r => r.name === roleName);
      if (!role) continue;
      actions.forEach(a => { const p = `${g.module}.${a}`; if (ALL.includes(p) && !role.permissions.includes(p)) role.permissions.push(p); });
      db.appliedGrants.push(key);
      changed = true;
    }
  }
  return changed;
}

function userByName(db, username) {
  return db.users.find(u => u.username.toLowerCase() === String(username || '').toLowerCase());
}

function permissionsOf(db, user) {
  if (!user || !user.enabled) { return []; }
  const set = new Set();
  db.roles.filter(r => user.roleIds.includes(r.id)).forEach(r => r.permissions.forEach(p => set.add(p)));
  return [...set].sort();
}

module.exports = { MODULES, ACTION_LABELS, ALL, seedRoles, seedUsers, ensure, userByName, permissionsOf, generated };
